// src/pages/DeliveryDashboardPage.tsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";

interface Delivery {
  _id: string;
  customerId: string;
  status: string;
}

export default function DeliveryDashboardPage() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const [q, setQ] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    axios
      .get<Delivery[]>("http://localhost:5000/api/delivery")
      .then((r) => setDeliveries(r.data))
      .catch(() => alert("❌ fetch failed"));
  }, []);

  const del = async (id: string) => {
    if (!window.confirm("Delete?")) return;
    try {
      await axios.delete(`http://localhost:5000/api/delivery/${id}`);
      setDeliveries((p) => p.filter((d) => d._id !== id));
    } catch {
      alert("❌ delete failed");
    }
  };

  const items = deliveries.filter((d) =>
    d.customerId.toLowerCase().includes(q.toLowerCase()) ||
    d.status.toLowerCase().includes(q.toLowerCase())
  );

  return (
    <div style={{ padding: 20, display: "flex", flexDirection: "column", minHeight: "100vh" }}>
      <header style={{ background: "#e1f5fe", padding: 12, display: "flex", alignItems: "center" }}>
        <h2 style={{ color: "#01579b", margin: 0 }}>Delivery Dashboard</h2>
        <div style={{ marginLeft: "auto", display: "flex", gap: 8 }}>
          <Link to="/delivery/new"><button style={btn}>+ New Delivery</button></Link>
          <Link to="/driver/new"  ><button style={btn}>+ Add Driver</button></Link>
          <Link to="/analytics"   ><button style={btn}>📈 Analytics</button></Link>
        </div>
      </header>

      <main style={{ flex: 1, background: "#fafafa", padding: 20 }}>
        <input
          placeholder="Search…"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          style={{ width: 300, padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
        />

        <table style={{ width: "100%", borderCollapse: "collapse", marginTop: 16 }}>
          <thead>
            <tr>
              <th style={th}>Customer ID</th>
              <th style={th}>Status</th>
              <th style={th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((d) => (
              <tr key={d._id}>
                <td style={td}>{d.customerId}</td>
                <td style={td}>{d.status}</td>
                <td style={td}>
                  <button style={actionBtn} onClick={() => navigate(`/delivery/${d._id}`)}>View</button>
                  <button style={editBtn}   onClick={() => navigate(`/edit-delivery/${d._id}`)}>Edit</button>
                  <button style={deleteBtn} onClick={() => del(d._id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </main>

      <footer style={{ background: "#e1f5fe", padding: 12, textAlign: "center" }}>
        © 2025 Delivery Dashboard
      </footer>
    </div>
  );
}

const th: React.CSSProperties = { borderBottom: "2px solid #bbb", padding: 8, textAlign: "left" };
const td: React.CSSProperties = { borderBottom: "1px solid #ddd", padding: 8 };
const btn: React.CSSProperties = {
  padding: "8px 12px",
  background: "#0288d1",
  color: "#fff",
  border: "none",
  borderRadius: 4,
  cursor: "pointer",
};
const actionBtn = { ...btn, marginRight: 6, fontSize: "0.9em", padding: "4px 8px" };
const editBtn   = { ...actionBtn, background: "#ffc107", color: "#000" };
const deleteBtn = { ...actionBtn, background: "#dc3545" };
